import { useEffect, useState } from "react";
import { refreshSoon } from "../engine/scroll";

// Story images come from story/public/img (generated by `npm run images` from story/assets-src).
// Until an image exists, a tinted placeholder in the scene's light keeps layout and mood intact.

interface ManifestEntry {
  w: number;
  h: number;
  color: string;
  widths: number[];
}
type Manifest = Record<string, ManifestEntry>;

let manifestPromise: Promise<Manifest> | null = null;
function loadManifest(): Promise<Manifest> {
  manifestPromise ??= fetch("/img/manifest.json")
    .then((r) => (r.ok ? r.json() : {}))
    .catch(() => ({}));
  return manifestPromise;
}

const MOOD: Record<string, string> = {
  night: "radial-gradient(120% 90% at 70% 40%, #3a2f45 0%, #1c1a2b 45%, #0e0d16 100%)",
  lamp: "radial-gradient(90% 80% at 72% 45%, #8a5a3b 0%, #3b2a2f 45%, #151320 100%)",
  studio: "radial-gradient(110% 90% at 30% 35%, #e9c9a8 0%, #c8875e 45%, #5a3324 100%)",
  clay: "radial-gradient(100% 90% at 50% 50%, #d9895c 0%, #a3532f 50%, #4a2416 100%)",
  morning: "radial-gradient(110% 90% at 25% 30%, #fff1d0 0%, #f1c27d 40%, #b97a45 100%)",
  office: "radial-gradient(110% 90% at 35% 45%, #3d5a80 0%, #1f2d44 50%, #0b111c 100%)",
  cream: "linear-gradient(160deg, #f6efe6, #ead9c5)",
};

const DEFAULT_MOOD: Record<string, keyof typeof MOOD> = {
  "P1-01": "lamp", "P1-02": "clay", "P1-03": "studio", "P1-04": "lamp", "P1-05": "lamp", "P1-06": "office",
  "P1-07": "night", "P1-08": "morning", "P1-08b": "morning", "P1-09": "morning", "P1-10": "studio",
};

export function Picture({ id, alt, className, sizes = "100vw", mood, priority = false }: {
  id: string;
  alt: string;
  className?: string;
  sizes?: string;
  mood?: keyof typeof MOOD;
  priority?: boolean;
}) {
  const [entry, setEntry] = useState<ManifestEntry | null | undefined>(undefined);

  useEffect(() => {
    let alive = true;
    loadManifest().then((m) => alive && setEntry(m[id] ?? null));
    return () => {
      alive = false;
    };
  }, [id]);

  const bg = MOOD[mood ?? DEFAULT_MOOD[id] ?? "cream"];
  if (!entry) {
    return <div className={`pic pic-placeholder ${className ?? ""}`} style={{ background: bg }} role="img" aria-label={alt} />;
  }
  const set = (fmt: string) => entry.widths.map((w) => `/img/${id}-${w}.${fmt} ${w}w`).join(", ");
  return (
    <picture className={`pic ${className ?? ""}`} style={{ background: entry.color }}>
      <source type="image/avif" srcSet={set("avif")} sizes={sizes} />
      <source type="image/webp" srcSet={set("webp")} sizes={sizes} />
      <img
        src={`/img/${id}-${entry.widths[Math.min(1, entry.widths.length - 1)]}.webp`}
        alt={alt}
        width={entry.w}
        height={entry.h}
        loading={priority ? "eager" : "lazy"}
        decoding="async"
        fetchPriority={priority ? "high" : "auto"}
        onLoad={refreshSoon}
      />
    </picture>
  );
}
